import{at as e,it as t,t as n,yt as r}from"./chunks/framework.Dyi9RH6t.js";var i=JSON.parse(`{"title":"LLM Optimized Documentation","description":"Where to find llms.txt, llms-full.txt, and the plain-Markdown twin of every page, and how the Copy page button uses them.","frontmatter":{"title":"LLM Optimized Documentation","description":"Where to find llms.txt, llms-full.txt, and the plain-Markdown twin of every page, and how the Copy page button uses them."},"headers":[],"relativePath":"llm-docs.md","filePath":"llm-docs.md"}`),a={name:`llm-docs.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h2 id="llm-optimized-documentation" tabindex="-1">LLM Optimized Documentation <a class="header-anchor" href="#llm-optimized-documentation" aria-label="Permalink to “LLM Optimized Documentation”">​</a></h2><p>Every page on this site is also published as plain Markdown, for coding agents and for anyone who wants to paste a page into a chat.</p><ul><li><a href="/pr-preview/pr-11292/llms.txt">llms.txt</a> is the table of contents: one absolute link per page, grouped by section, following the <a href="https://llmstxt.org/" target="_blank" rel="noreferrer">llms.txt</a> convention.</li><li><a href="/pr-preview/pr-11292/llms-full.txt">llms-full.txt</a> is every page concatenated into one file. It is a few megabytes; prefer <code>llms.txt</code> plus the one page you need.</li><li>Any page&#39;s Markdown is at its URL plus <code>.md</code>: <code>/guides/the-manual/requests/builders</code> becomes <code>/guides/the-manual/requests/builders.md</code>. For a URL that ends in <code>/</code>, drop the slash first (<code>/guides/installation/</code> becomes <code>/guides/installation.md</code>) or append <code>index.md</code>; both exist.</li><li>The <strong>Copy page</strong> button above every page title does the same without the URL juggling: copy the Markdown, open it in a new tab, or hand the page to Claude.</li></ul><p>Agents working in an app that depends on <strong><em>Warp</em>Drive</strong> get these rules from the <a href="/pr-preview/pr-11292/skills/docs/read-the-docs-as-markdown">Read the Docs as Markdown</a> skill in <a href="https://www.npmjs.com/package/@warp-drive/memory-alpha" target="_blank" rel="noreferrer"><code>@warp-drive/memory-alpha</code></a>, including how to read the site&#39;s <code>:::tip</code> callouts and <code>:::tabs</code> blocks in their raw form.</p>`,4)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};